WITH with_prev AS (SELECT *, LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) AS prev_event_time FROM web_events), flagged AS (SELECT *, CASE WHEN prev_event_time IS NULL OR event_time > prev_event_time + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM with_prev) SELECT id, session_id, event_type, event_time, duration_sec, SUM(session_start_flag) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged;
